insert into public.coach_messages (id, client_id, sender_id, body, created_at, read_at) values
('71468ee6-f384-535b-8595-438feca3d167', '4f9eada9-e34d-5199-b5eb-e898e8624163', '0ee55b55-63f1-5ca0-a7fe-df00f913ce26', 'Hey Luke, can we swap Wednesday to Thursday this week? Work thing.', pg_temp.ts(3, '07:12'), pg_temp.ts(3, '21:00')),
('c9dcaf94-6730-5be4-b77a-a035cbb196a5', '4f9eada9-e34d-5199-b5eb-e898e8624163', '9287e733-61a0-4b98-8452-afb80bc3129f', 'No worries, moved it to Thursday for you.', pg_temp.ts(3, '08:40'), pg_temp.ts(3, '21:00')),
('1f5f15c2-942a-52ae-bfd8-b1f26e8245f8', '4f9eada9-e34d-5199-b5eb-e898e8624163', '0ee55b55-63f1-5ca0-a7fe-df00f913ce26', 'Legend, thank you!', pg_temp.ts(3, '08:52'), pg_temp.ts(3, '21:00')),
('d78137f0-c669-56ef-800c-2b3b4522f17d', 'ec400a7c-a5a0-5690-9ce6-3a656bef73c9', 'df5d4d09-7a7a-5e09-84c8-94e9a199139d', 'Is it worth adding pause reps on bench?', pg_temp.ts(4, '18:30'), pg_temp.ts(4, '21:00')),
('ecc48e15-0e8a-513f-a6a3-d95bcbaa2d3b', 'ec400a7c-a5a0-5690-9ce6-3a656bef73c9', '9287e733-61a0-4b98-8452-afb80bc3129f', 'Yes, on your second bench movement. 2 second pause, same weight as your last set of 5.', pg_temp.ts(4, '19:05'), pg_temp.ts(4, '21:00')),
('c0d9524e-7d0d-5f89-b0b6-c3cc3ead830c', 'ec400a7c-a5a0-5690-9ce6-3a656bef73c9', 'df5d4d09-7a7a-5e09-84c8-94e9a199139d', 'Hit 92.5 for 3 on bench tonight!! 100 by Easter is on', pg_temp.ts(2, '18:41'), null),
('a5194c3a-9f15-537e-8955-03e2d40871fb', 'e91b1716-319d-5445-89cd-cac49ec4d93e', 'effac3b2-cbb9-567e-be15-834db2327f05', 'Hammy felt a bit tight after sprints. Should I skip the RDLs on Thursday?', pg_temp.ts(1, '20:02'), null),
('768ee994-b042-56eb-beab-4f252c2c0429', 'cb2eb714-87b9-5a83-990a-709e82848d2e', '9287e733-61a0-4b98-8452-afb80bc3129f', 'How''s the sleep going with the little one?', pg_temp.ts(6, '12:15'), pg_temp.ts(6, '21:00')),
('5b7a59bf-ef68-5ba7-834f-c98066b0544f', 'cb2eb714-87b9-5a83-990a-709e82848d2e', 'd8954040-3845-506c-8373-07d7b2929f31', 'Better this week, about 6 hours most nights. Feeling stronger already.', pg_temp.ts(6, '13:02'), pg_temp.ts(6, '21:00')),
('535f480e-d91f-5201-9a0e-d0dea867a893', 'cb2eb714-87b9-5a83-990a-709e82848d2e', '9287e733-61a0-4b98-8452-afb80bc3129f', 'That''s a big win. Keep Saturdays as your heavy day.', pg_temp.ts(6, '13:20'), pg_temp.ts(6, '21:00')),
('c1c72b63-513b-5aa8-9a8c-9a5008856f2f', 'ef38f776-813f-541c-b249-820e0761b8cd', '06e02505-00e1-5250-96dc-27f2f331dbf8', 'Ran 7 km without stopping on Sunday!', pg_temp.ts(8, '17:10'), pg_temp.ts(8, '21:00')),
('e0e523ef-094e-5de5-b4ae-15629efa168a', 'ef38f776-813f-541c-b249-820e0761b8cd', '9287e733-61a0-4b98-8452-afb80bc3129f', 'Huge. We''ll add a fourth run in two weeks.', pg_temp.ts(8, '17:45'), pg_temp.ts(8, '21:00')),
('cc0b3c3f-5909-5252-a813-a866471765f6', '62124aab-f8ef-5c4a-85bf-2d4b80f21efd', '9287e733-61a0-4b98-8452-afb80bc3129f', 'Hey Sophie, haven''t heard from you this week. How are you going?', pg_temp.ts(4, '10:05'), pg_temp.ts(4, '21:00'));
insert into public.pt_notes (id, client_id, pt_id, text, created_at) values
('1b3659e6-7162-58db-a700-1b3563094d0f', '4f9eada9-e34d-5199-b5eb-e898e8624163', '9287e733-61a0-4b98-8452-afb80bc3129f', 'Wedding is 21 March. Wants toned arms for the dress. Prefers 6 am sessions before work.', pg_temp.ts(83, '11:00')),
('fa275fd6-4b82-530e-901f-7c15fffb6d57', 'ec400a7c-a5a0-5690-9ce6-3a656bef73c9', '9287e733-61a0-4b98-8452-afb80bc3129f', 'Competitive and loves numbers. Show him his PB graph every few weeks.', pg_temp.ts(104, '11:00')),
('2796b5b3-820d-54b6-b7cd-a3d3ec403040', 'cb2eb714-87b9-5a83-990a-709e82848d2e', '9287e733-61a0-4b98-8452-afb80bc3129f', 'Baby born in May. Trains while her partner has the kids on Saturday. Pelvic floor first.', pg_temp.ts(41, '11:00'));
